        in.nextToken();
        int n = (int) in.nval;
        int[] inorder = new int[n], postorder = new int[n];
        for (int i = 0; i < n; i++) { in.nextToken(); inorder[i] = (int) in.nval; }
        for (int i = 0; i < n; i++) { in.nextToken(); postorder[i] = (int) in.nval; }
        int[] res = preorder(inorder, postorder);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
